    // PURPOSE OF THIS MODULE:
    // Model the performance of cooling towers

    std::string const cCoolingTower_SingleSpeed("CoolingTower:SingleSpeed");
    std::string const cCoolingTower_TwoSpeed("CoolingTower:TwoSpeed");
